package pages;
import com.microsoft.playwright.Page;
import framework.CommonMethods;
public final class LoginPage {
  private final Page page;
  public LoginPage(Page page) { this.page = page; }
  public void open() { page.navigate(String.valueOf(CommonMethods.testData().getOrDefault("baseUrl", "https://www.saucedemo.com"))); }
  public void login(String username, String password) { page.getByPlaceholder("Username").fill(username); page.getByPlaceholder("Password").fill(password); page.getByRole(com.microsoft.playwright.options.AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Login")).click(); }
  public void loginWithValidCredentials() { var user = (java.util.Map<?, ?>) CommonMethods.testData().get("validUser"); login(String.valueOf(user.get("username")), String.valueOf(user.get("password"))); }
  public boolean inventoryVisible() { var heading = page.getByText("Products", new Page.GetByTextOptions().setExact(true)); heading.waitFor(); return heading.isVisible(); }
}
